From 587df5474ce70b71403e8c5a6528bdc022c62c95 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:21:08 +0100
Subject: [PATCH] containments/desktop: make rubber band selection cheaper

Each pointer move hit-tested all items per cell, and each selection
change reloaded every role of the icons and rebuilt the actions. Find
delegates by index, forward changed roles, update actions at the end.

BUG: 493376
---
 .../package/contents/ui/FolderView.qml        | 38 ++++---------------
 .../desktop/plugins/folder/foldermodel.cpp    |  9 ++++-
 .../desktop/plugins/folder/foldermodel.h      |  1 +
 .../desktop/plugins/folder/positioner.cpp     |  2 +-
 4 files changed, 17 insertions(+), 33 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..14f65bce0d 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -905,40 +905,16 @@ FocusScope {
                 }

                 function rectangleSelect(x, y, width, height, rubberBand) {
-                    const rows = (gridView.flow === GridView.FlowLeftToRight);
-                    const stripes = Math.ceil(gridView.count / positioner.perStripe);
-                    const cWidth = gridView.cellWidth - (2 * Kirigami.Units.smallSpacing);
-                    const cHeight = gridView.cellHeight - (2 * Kirigami.Units.smallSpacing);
-                    const midWidth = gridView.cellWidth / 2;
-                    const midHeight = gridView.cellHeight / 2;
                     let indices = [];

-                    for (let s = 0; s < stripes; s++) {
-                        for (let i = 0; i < positioner.perStripe; i++) {
-                            let index = (s * positioner.perStripe) + i;
-
-                            if (index >= gridView.count) {
-                                break;
-                            }
-
-                            if (positioner.isBlank(index)) {
-                                continue;
-                            }
-
-                            let itemX = ((rows ? i : s) * gridView.cellWidth);
-                            let itemY = ((rows ? s : i) * gridView.cellHeight);
-
-                            if (gridView.effectiveLayoutDirection === Qt.RightToLeft) {
-                                itemX -= (rows ? gridView.contentX : gridView.originX);
-                                itemX += cWidth;
-                                itemX = (rows ? gridView.width : gridView.contentItem.width) - itemX;
-                            }
-
-                            const item = gridView.contentItem.childAt(itemX + midWidth, itemY + midHeight);
-                            if (item && rubberBand.intersects(Qt.rect(item.x, item.y, item.width, item.height))) {
-                                indices.push(index)
-                            }
+                    for (let index = 0; index < gridView.count; index++) {
+                        if (positioner.isBlank(index)) {
+                            continue;
+                        }

+                        const item = gridView.itemAtIndex(index);
+                        if (item && rubberBand.intersects(Qt.rect(item.x, item.y, item.width, item.height))) {
+                            indices.push(index)
                         }
                     }

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..8889a715a3 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -1111,11 +1111,14 @@ void FolderModel::clearSelection()
 void FolderModel::pinSelection()
 {
     m_pinnedSelection = m_selectionModel->selection();
+    m_selectionPinned = true;
 }

 void FolderModel::unpinSelection()
 {
     m_pinnedSelection = QItemSelection();
+    m_selectionPinned = false;
+    updateActions();
 }

 void FolderModel::addItemDragImage(int row, int x, int y, int width, int height, const QVariant &image)
@@ -1517,7 +1520,11 @@ void FolderModel::changeSelection(const QItemSelection &selected, const QItemSel
         }
     }

-    updateActions();
+    // While a rubber band selection is in progress the selection changes on every pointer move,
+    // so the actions are only updated once it ends
+    if (!m_selectionPinned) {
+        updateActions();
+    }
 }

 bool FolderModel::isBlank(int row) const
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..71ecc71085 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -375,6 +375,7 @@ private:
     mutable QHash<QUrl, KIO::StatJob *> m_isDirJobs;
     QItemSelectionModel *m_selectionModel;
     QItemSelection m_pinnedSelection;
+    bool m_selectionPinned = false;
     QModelIndexList m_dragIndexes;
     QHash<int, DragImage *> m_dragImages;
     QPoint m_dragHotSpotScrollOffset;
diff --git a/containments/desktop/plugins/folder/positioner.cpp b/containments/desktop/plugins/folder/positioner.cpp
index 8fc7ec4c6c..89a868e0d5 100644
--- a/containments/desktop/plugins/folder/positioner.cpp
+++ b/containments/desktop/plugins/folder/positioner.cpp
@@ -596,7 +596,7 @@ void Positioner::sourceDataChanged(const QModelIndex &topLeft, const QModelIndex
         for (int i = start; i <= end; ++i) {
             if (m_sourceToProxy.contains(i)) {
                 const QModelIndex &idx = index(m_sourceToProxy.value(i), 0);
-                Q_EMIT dataChanged(idx, idx);
+                Q_EMIT dataChanged(idx, idx, roles);
             }
         }
     } else {
